CREATE DATABASE IF NOT EXISTS store_demo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE store_demo;
CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','customer') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,description TEXT NOT NULL,base_price DECIMAL(10,2) NOT NULL,image_url VARCHAR(500) DEFAULT NULL,stock_quantity INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_code VARCHAR(32) NOT NULL UNIQUE,user_id INT UNSIGNED DEFAULT NULL,total_amount DECIMAL(10,2) NOT NULL,order_status ENUM('Pending','Processing','Shipped','Delivered','Cancelled') NOT NULL DEFAULT 'Pending',shipping_address TEXT NOT NULL,payment_method ENUM('Mock Card','Cash on Delivery') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id INT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
INSERT IGNORE INTO categories(name,slug) VALUES('Home Goods','home-goods'),('Accessories','accessories'),('Stationery','stationery');
INSERT INTO products(category_id,name,description,base_price,stock_quantity) SELECT id,'Everyday Tote','A roomy carryall for everyday essentials.',24,20 FROM categories WHERE slug='accessories' AND NOT EXISTS(SELECT 1 FROM products WHERE name='Everyday Tote');
INSERT INTO products(category_id,name,description,base_price,stock_quantity) SELECT id,'Ceramic Mug','A tactile mug for slow mornings.',18,15 FROM categories WHERE slug='home-goods' AND NOT EXISTS(SELECT 1 FROM products WHERE name='Ceramic Mug');
INSERT INTO products(category_id,name,description,base_price,stock_quantity) SELECT id,'Desk Notebook','A clean page for your next idea.',12,30 FROM categories WHERE slug='stationery' AND NOT EXISTS(SELECT 1 FROM products WHERE name='Desk Notebook');
